<?php $pageTitle=page_title('Announcements'); $page='admin-announcements'; ?>
<div class="dashboard-head reveal"><div><span class="eyebrow">Platform communication</span><h1>Announcements</h1><p>Publish timely market-day updates without changing the core catalog.</p></div></div>
<div class="detail-grid"><form class="content-card card" method="post" action="<?= e(url('admin-announcement-save')) ?>"><?= csrf_field() ?><div class="content-head"><div><h2>New announcement</h2><p>Published messages appear on the public home page.</p></div><span class="feature-icon" style="margin:0"><?= icon('bell') ?></span></div><div class="form-group"><label for="announcement_title">Title</label><input id="announcement_title" name="title" type="text" minlength="3" maxlength="120" required></div><div class="form-group"><label for="announcement_message">Message</label><textarea id="announcement_message" name="message" minlength="5" maxlength="800" required></textarea></div><div class="form-grid"><div class="form-group"><label for="announcement_status">Status</label><select id="announcement_status" name="status"><option value="published">Publish now</option><option value="draft">Save as draft</option></select></div><div class="form-group"><label for="announcement_expiry">Expires on <small>(optional)</small></label><input id="announcement_expiry" name="expires_at" type="date" min="<?= e(date('Y-m-d')) ?>"></div></div><button class="btn" type="submit">Save announcement <?= icon('arrow-right') ?></button></form>
<div class="content-card card"><div class="content-head"><div><h2>Announcement history</h2><p><?= count($announcements) ?> saved messages</p></div></div><?php if($announcements): ?><div class="timeline"><?php foreach($announcements as $announcement): ?><div class="timeline-item"><strong><?= e($announcement['title']) ?> <?= status_pill($announcement['status']) ?></strong><span><?= e($announcement['message']) ?></span><span><?= e($announcement['author_name'] ?? 'System') ?> · <?= format_date($announcement['created_at'],'M j, Y') ?><?php if($announcement['expires_at']): ?> · expires <?= format_date($announcement['expires_at']) ?><?php endif; ?></span></div><?php endforeach; ?></div><?php else: ?><div class="empty-state"><span class="empty-state-icon">📣</span><h3>No announcements yet</h3><p>Publish the first platform update.</p></div><?php endif; ?></div></div>
